def _panels(study, z):
    from scipy.optimize import least_squares
    c = study['panel_c']
    (u, v1, v2) = (np.asarray(c[k]) for k in ('u', 'v1', 'v2'))

    def first(u, p):
        (a, b, c) = p
        return _bias(np.tanh(a * u) + c * np.roll(np.sin(b * u), 1, axis=1))

    def second(u, p):
        return _bias(np.cos(p[0] * u))

    def proj(p, make, v):
        f = make(u, p)
        return (f @ _ls(f, v) - v).ravel()
    p1 = least_squares(proj, [1.75, 2.1, 0.3], args=(first, v1), bounds=([1, 1.5, 0], [2.5, 2.8, 0.6])).x
    p2 = least_squares(proj, [2.4], args=(second, v2), bounds=([1.8], [3.0])).x
    return np.column_stack([f(z, p) @ _ls(f(u, p), v) for (f, p, v) in ((first, p1, v1), (second, p2, v2))])

def design(t, v1, v2):
    (f, g) = (v1(t), v2(t))
    h = _bias(np.column_stack([f, g]))
    return np.column_stack([h, np.sum(f * g, axis=1), f[:, 0] * g[:, 1]])
